local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3d0643141edfff99"] = { "La tua prossima scelta ti attende.\n\nSei in missione diplomatica per conto del tuo signore presso un paese crudele, attualmente in guerra con il tuo. La guerra è costata cara a entrambe le parti. Il tuo compito è ottenere una pace onorevole per entrambi i popoli.\n\nA una cena diplomatica senti il sovrano della terra nemica insultare ferocemente il tuo benevolo signore. Sei quasi <certo/certa> che il sovrano non volesse farsi sentire da te, ma ha comunque infangato l'onore del tuo signore.\n\nFai la tua scelta.", "." },
  ["3d0a2355190bb927"] = { "I tuoi attacchi sono rallentati dal freddo, mi pare!", "." },
  ["3d1c65a2c89be78b"] = { "Nessun riposo... per i morti adirati!", "." },
  ["3d2167141510a515"] = { "Guarda dove metti i piedi, {class}, perché ho un incantesimo di metamorfosi con il tuo nome sopra...", "." },
  ["3d2197755c18b93a"] = { "Ho forgiato la ⟦Soul Gem=Gemma dell'Anima⟧ di Yenniku, {name}...", "." },
  ["3d2240c4a49a76e9"] = { "Grazie per l'offerta, {class}. Purtroppo non hai ancora abbastanza esperienza per affrontare i pericoli del ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["3d28948f63e83bc8"] = { "Tartufi!", "." },
  ["3d2951a82ba9054a"] = { "{class}, abbiamo un gran bisogno del tuo aiuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧. E c'è persino più onore e reputazione da guadagnare con i ⟦Warsong Outriders=Predoni Cantaguerra⟧! Hai il coraggio di scendere in battaglia?", "." },
  ["3d33b72528814c6d"] = { "Di recente un druido elfo della notte di nome Naralex scoprì una rete di caverne sotterranee nel cuore delle ⟦Barrens=Savane⟧. Convinto di poter usare le sorgenti delle caverne per riportare il rigoglio nelle ⟦Barrens=Savane⟧, il druido cominciò ad attingere alle energie del leggendario ⟦Emerald Dream=Sogno di Smeraldo⟧. La sua visione però si trasformò in un incubo, e presto la ⟦Wailing Caverns=Caverna dei Lamenti⟧ divenne una tana di predatori feroci e letali. Si dice che Naralex si trovi ancora da qualche parte nel labirinto, intrappolato oltre i confini del ⟦Emerald Dream=Sogno di Smeraldo⟧.", "." },
  ["3d41988fe22a669a"] = { "Eh, eh... Sei proprio un tipo curioso, eh, {name}? Be', ecco cosa devi fare.\n\nA nord di qui, tra le vecchie rovine, vive uno gnoll molto sgradevole di nome Miblon Snarltooth. Fa la guardia all'unica Evoroot che io conosca, ma la sorveglia giorno e notte! Pare che non dorma mai!\n\nQuello che puoi fare è corromperlo. Posso venderti un'esca che troverà gustosa: mettila a terra vicino a lui e lo distrarrà abbastanza a lungo da permetterti di prendere la Evoroot. Buona fortuna!", "." },
  ["3d46431167d289a2"] = { "I cannoni devono essere pronti presto.", "." },
  ["3d4c15087f30c106"] = { "Grazie per avermi liberato. Parla con mia sorella a Troncorotto. Io... devo trovare un posto per riposare...", "." },
  ["3d5f4ac5c391f21b"] = { "La tua arma del Vil è pronta, {name}.", "." },
  ["3d62c09685b9234e"] = { "%s sente il richiamo della battaglia e si alza per servire il suo padrone.", "." },
  ["3d6822aece9196a0"] = { "Allora è con Komin ⟦Winterhoof=Zoccolo Artico⟧ che devi parlare, a Holistic Herbalism. Lo trovi sull'altura di mezzo.", "." },
  ["3d6960ac71e41d3d"] = { "È uno scherzo, per caso?", "." },
  ["3d6f673466433aaf"] = { "Arrr... faresti meglio a non sprecare il mio tempo, compare!", "." },
  ["3d71039b0684cd62"] = { "Osate versare sangue su un terreno neutrale? FUORI! FUORI, HO DETTO!", "." },
  ["3d7867c1fb6be2f1"] = { "Per mantenere il collegamento con la terraferma, abbiamo ippogrifi che volano di continuo tra ⟦Rut'theran Village=Rut'theran⟧ e ⟦Darkshore=Rivafosca⟧.", "." },
  ["3d7d7d6b21125df0"] = { "Ah, questo sì che ci vuole! Credo che me ne prenderò un altro paio... puoi tenermi d'occhio questi barili, {name}?", "." },
  ["3d7e4e7b2e35e130"] = { "Scavare troppo a fondo nel tuo passato potrebbe mettere bruscamente fine al tuo futuro.", "." },
  ["3d80cd06edff8416"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo distruggerà!", "." },
  ["3d8157ca5b51bb01"] = { "<Coraggioso/Coraggiosa> {class}, grazie per avermi salvato! Di certo il maresciallo Marris ricompenserà la tua buona azione, {name}.", "." },
  ["3d85980627f78b42"] = { "Sembra che l'influenza dello Stormo dei Draghi Neri si fosse estesa oltre i confini delle ⟦Burning Steppes=Steppe Ardenti⟧, fino al regno stesso di ⟦Stormwind=Roccavento⟧! L'usurpatore è stato smascherato e cacciato.", "." },
  ["3d8aaec7e8ebb391"] = { "Earthen Templar! Possiedo il tuo stemma di richiamo. Rispondi alla mia chiamata!", "." },
  ["3d96988b3a0f12b9"] = { "Confessa e ti lasceremo andare.", "." },
  ["3d98ecf32f7174bd"] = { "Con l'approvazione di lord Varimathras, gli ⟦Deathstalkers=Inseguitori della Morte⟧ crescono di numero. Più lame per colpire i nostri nemici quando meno se lo aspettano.", "." },
  ["3db750c4c4cd346d"] = { "Mi dicono che un tempo le fattorie delle ⟦Westfall=Marche Occidentali⟧ fornissero a ⟦Stormwind=Roccavento⟧ raccolti abbondanti. Ma ora il suolo è sterile e la maggior parte dei contadini è fuggita.\r\n\nA nome di Darnassus vorrei offrire il mio aiuto per far rifiorire questa terra. Mi darai una mano?", "." },
  ["3dbdb4902e01c32d"] = { "Miei cari... miei cari...", "." },
  ["3dc0dff54b79e582"] = { "Ora nessuno ti salverà, umano!", "." },
  ["3dc2fe4952d957ab"] = { "Vecchio re morto? È impossibbile!", "." },
  ["3dcaaaa53fa711bf"] = { "Cosa? Non conosco nessun istruttore di stregoni a ⟦Stormwind=Roccavento⟧.\n\nAnche se... C'è chi ha notato attività demoniache dalle parti dello Slaughtered Lamb, nel ⟦Mage Quarter=Quartiere dei Maghi⟧. Potresti dare un'occhiata lì.", "." },
  ["3dd166b4c0b433a9"] = { "Ti do il benvenuto a ⟦Darkshire=Borgoscuro⟧. Sono l'impiegato Daltry, al tuo servizio. Posso esserti d'aiuto?", "." },
  ["3dd27061dcb14c28"] = { "Hazza'rah, il Tessitore di Sogni.\n\nSuo è il potere degli incubi, e che i suoi nemici possano dormire per sempre.\n\nOra Hazza'rah sogna sull'orlo della follia.", "." },
  ["3dda1f2599d93798"] = { "Cos'è lo sforzo bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧?", "." },
  ["3deebb3ba568bda6"] = { "EVVIVA! SONO IN SALVO!", "." },
  ["3df2828cc71739dc"] = { "Il capitano Galvangar è caduto! Onorate il nostro capitano caduto e scatenatevi di nuovo contro l'⟦Alliance=Alleanza⟧!", "." },
})
